// src/components/pages/Landing.jsx
import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import PageWrapper from "../PageWrapper"; // assuming you wrap your pages

const Landing = () => {
  const navigate = useNavigate();

  return (
    <PageWrapper>
      <div className="flex flex-col items-center justify-center min-h-screen px-6 text-center bg-gradient-to-br from-indigo-50 via-purple-50 to-pink-50">
        
        {/* Hero Heading */}
        <motion.h1
          initial={{ y: -40, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="text-5xl md:text-6xl font-extrabold text-gray-900 mb-6"
          style={{ fontFamily: "'Poppins', 'Inter', sans-serif" }}
        >
          Welcome to Your{" "}
          <span className="text-indigo-600">AI Interview Coach</span>
        </motion.h1>

        {/* Subheading */}
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
          className="max-w-2xl text-gray-700 text-xl md:text-2xl mb-10 leading-relaxed"
          style={{ fontFamily: "'Poppins', 'Inter', sans-serif" }}
        >
          Get personalized, AI-powered feedback to boost your confidence and 
          improve your interview performance.
        </motion.p>

        {/* Start Learning Button */}
        <motion.button
          whileHover={{ scale: 1.05, boxShadow: "0 8px 20px rgba(0,0,0,0.2)" }}
          whileTap={{ scale: 0.95 }}
          onClick={() => navigate("/login")}
          className="bg-indigo-600 hover:bg-indigo-700 text-white text-lg md:text-xl px-12 py-4 rounded-full shadow-lg transition-all duration-300"
        >
          Start Learning 🚀
        </motion.button>

      </div>
    </PageWrapper>
  );
};

export default Landing;
